  1798  // Construct output meshes
  1799  void MDLImporter::GenerateOutputMeshes_3DGS_MDL7(
  1800          MDL::IntGroupData_MDL7 &groupData,
  1801          MDL::IntSplitGroupData_MDL7 &splitGroupData) {
  1802      const MDL::IntSharedData_MDL7 &shared = splitGroupData.shared;
  1803
  1804      // get a pointer to the header ...
  1805      const MDL::Header_MDL7 *const pcHeader = (const MDL::Header_MDL7 *)this->mBuffer;
  1806      const unsigned int iNumOutBones = pcHeader->bones_num;
  1807
  1808      for (std::vector<aiMaterial *>::size_type i = 0; i < shared.pcMats.size(); ++i) {
  1809          if (!splitGroupData.aiSplit[i]->empty()) {
  1810
  1811              // allocate the output mesh
  1812              aiMesh *pcMesh = new aiMesh();
  1813
  1814              pcMesh->mPrimitiveTypes = aiPrimitiveType_TRIANGLE;
  1815              pcMesh->mMaterialIndex = (unsigned int)i;
  1816
  1817              // allocate output storage
  1818              pcMesh->mNumFaces = (unsigned int)splitGroupData.aiSplit[i]->size();
  1819              pcMesh->mFaces = new aiFace[pcMesh->mNumFaces];
  1820
  1821              pcMesh->mNumVertices = pcMesh->mNumFaces * 3;
  1822              pcMesh->mVertices = new aiVector3D[pcMesh->mNumVertices];
  1823              pcMesh->mNormals = new aiVector3D[pcMesh->mNumVertices];
  1824
  1825              if (!groupData.vTextureCoords1.empty()) {
  1826                  pcMesh->mNumUVComponents[0] = 2;
  1827                  pcMesh->mTextureCoords[0] = new aiVector3D[pcMesh->mNumVertices];
  1828                  if (!groupData.vTextureCoords2.empty()) {
  1829                      pcMesh->mNumUVComponents[1] = 2;
  1830                      pcMesh->mTextureCoords[1] = new aiVector3D[pcMesh->mNumVertices];
  1831                  }
  1832              }
  1833
  1834              // iterate through all faces and build an unique set of vertices
  1835              unsigned int iCurrent = 0;
  1836              for (unsigned int iFace = 0; iFace < pcMesh->mNumFaces; ++iFace) {
  1837                  pcMesh->mFaces[iFace].mNumIndices = 3;
  1838                  pcMesh->mFaces[iFace].mIndices = new unsigned int[3];
  1839
  1840                  unsigned int iSrcFace = splitGroupData.aiSplit[i]->operator[](iFace);
  1841                  const MDL::IntFace_MDL7 &oldFace = groupData.pcFaces[iSrcFace];
  1842
  1843                  // iterate through all face indices
  1844                  for (unsigned int c = 0; c < 3; ++c) {
  1845                      const uint32_t iIndex = oldFace.mIndices[c];
  1846                      pcMesh->mVertices[iCurrent] = groupData.vPositions[iIndex];
  1847                      pcMesh->mNormals[iCurrent] = groupData.vNormals[iIndex];
  1848
  1849                      if (!groupData.vTextureCoords1.empty()) {
  1850
  1851                          pcMesh->mTextureCoords[0][iCurrent] = groupData.vTextureCoords1[iIndex];
  1852                          if (!groupData.vTextureCoords2.empty()) {
  1853                              pcMesh->mTextureCoords[1][iCurrent] = groupData.vTextureCoords2[iIndex];
  1854                          }
  1855                      }
  1856                      pcMesh->mFaces[iFace].mIndices[c] = iCurrent++;
  1857                  }
  1858              }
  1859
  1860              // if we have bones in the mesh we'll need to generate
  1861              // proper vertex weights for them
  1862              if (!groupData.aiBones.empty()) {
  1863                  std::vector<std::vector<unsigned int>> aaiVWeightList;
  1864                  aaiVWeightList.resize(iNumOutBones);
  1865
  1866                  int iCurrentWeight = 0;
  1867                  for (unsigned int iFace = 0; iFace < pcMesh->mNumFaces; ++iFace) {
  1868                      unsigned int iSrcFace = splitGroupData.aiSplit[i]->operator[](iFace);
  1869                      const MDL::IntFace_MDL7 &oldFace = groupData.pcFaces[iSrcFace];
  1870
  1871                      // iterate through all face indices
  1872                      for (unsigned int c = 0; c < 3; ++c) {
  1873                          unsigned int iBone = groupData.aiBones[oldFace.mIndices[c]];
  1874                          if (UINT_MAX != iBone) {
  1875                              if (iBone >= iNumOutBones) {
  1876                                  ASSIMP_LOG_ERROR("Bone index overflow. "
  1877                                                   "The bone index of a vertex exceeds the allowed range. ");
  1878                                  iBone = iNumOutBones - 1;
  1879                              }
  1880                              aaiVWeightList[iBone].push_back(iCurrentWeight);
  1881                          }
  1882                          ++iCurrentWeight;
  1883                      }
  1884                  }
  1885                  // now check which bones are required ...
  1886                  for (std::vector<std::vector<unsigned int>>::const_iterator k = aaiVWeightList.begin(); k != aaiVWeightList.end(); ++k) {
  1887                      if (!(*k).empty()) {
  1888                          ++pcMesh->mNumBones;
  1889                      }
  1890                  }
  1891                  pcMesh->mBones = new aiBone *[pcMesh->mNumBones];
  1892                  iCurrent = 0;
  1893                  for (std::vector<std::vector<unsigned int>>::const_iterator k = aaiVWeightList.begin(); k != aaiVWeightList.end(); ++k, ++iCurrent) {
  1894                      if ((*k).empty())
  1895                          continue;
  1896
  1897                      // seems we'll need this node
  1898                      aiBone *pcBone = pcMesh->mBones[iCurrent] = new aiBone();
  1899                      pcBone->mName = aiString(shared.apcOutBones[iCurrent]->mName);
  1900                      pcBone->mOffsetMatrix = shared.apcOutBones[iCurrent]->mOffsetMatrix;
  1901
  1902                      // setup vertex weights
  1903                      pcBone->mNumWeights = (unsigned int)(*k).size();
  1904                      pcBone->mWeights = new aiVertexWeight[pcBone->mNumWeights];
